head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[chrckbox > P > validator]<br/>컴포넌트에서 포커스가 해제될때 입력값 검증을 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [        
        "입력값 검증을 위한 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 파라미터로 입력값과 대상 컴포넌트의 렌더링 ID 가 전달됩니다.",
        "사용자 정의 함수의 반환값이 새로운 입력값으로 적용됩니다.",
        "만약 사용자 정의 함수의 반환값으로 입력값이 수정되면 onchange -> onviewchange 순으로 이벤트가 발생합니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        validator: con_validator.getText(),      
        tabIndex: 1,
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "onviewchange"]);

    // target 생성
    $c.gcm.createLabel('label="validator 설정하면 포커스 해제 후 선택값 해제되어야 함(return -1 상태임)"', '', 'label1');
    $c.gcm.createBasicCheckBox(cList, eList);
}



scwin.fn_validator = function(val, id) { 
    wf_body_bottom.getObj("scwin").setReturnValue("val : " + val);
    wf_body_bottom.getObj("scwin").setReturnValue("id : " + id); 
    return -1;   
}



scwin.btn_getSelectedIndex_onclick = function (e) {
    let rtn = '';

    rtn = target1.getSelectedIndex();

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + rtn);	
};



scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
};



scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
};
